"""Core game state, input handling, rendering, and the main loop."""

from __future__ import annotations

import random
from dataclasses import dataclass

import pygame

from .config import Settings


Position = tuple[int, int]


@dataclass
class GameState:
    """Mutable state for a single round of Snake."""

    snake: list[Position]
    direction: Position
    food: Position
    game_over: bool = False

    @property
    def score(self) -> int:
        return len(self.snake) - 1


def random_food(settings: Settings, rng: random.Random | None = None) -> Position:
    """Return a food position aligned to the game's movement grid."""
    generator = rng or random
    max_x = (settings.width - settings.cell_size) // settings.cell_size
    max_y = (settings.height - settings.cell_size) // settings.cell_size
    return (
        generator.randint(0, max_x) * settings.cell_size,
        generator.randint(0, max_y) * settings.cell_size,
    )


def collides_with_self(head: Position, body: list[Position]) -> bool:
    """Return whether the new head overlaps an existing body segment."""
    return head in body[:-1]


class SnakeGame:
    """Pygame application that runs repeatable Snake rounds."""

    def __init__(self, settings: Settings | None = None) -> None:
        self.settings = settings or Settings()
        self.screen: pygame.Surface | None = None
        self.clock: pygame.time.Clock | None = None
        self.font: pygame.font.Font | None = None
        self.score_font: pygame.font.Font | None = None
        self.state: GameState | None = None

    def initialize(self) -> None:
        """Initialize Pygame resources needed by the game."""
        pygame.init()
        self.screen = pygame.display.set_mode(
            (self.settings.width, self.settings.height)
        )
        pygame.display.set_caption(self.settings.title)
        self.clock = pygame.time.Clock()
        self.font = pygame.font.SysFont("bahnschrift", 25)
        self.score_font = pygame.font.SysFont("comicsansms", 35)

    def reset_round(self) -> None:
        """Start a new round without calling the game loop recursively."""
        center = (
            self.settings.width // 2,
            self.settings.height // 2,
        )
        self.state = GameState(
            snake=[center],
            direction=(0, 0),
            food=random_food(self.settings),
        )

    def handle_events(self) -> bool:
        """Process input; return False when the window should close."""
        assert self.state is not None
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                return False
            if event.type == pygame.KEYDOWN:
                directions = {
                    pygame.K_LEFT: (-self.settings.cell_size, 0),
                    pygame.K_RIGHT: (self.settings.cell_size, 0),
                    pygame.K_UP: (0, -self.settings.cell_size),
                    pygame.K_DOWN: (0, self.settings.cell_size),
                }
                if event.key in directions:
                    self.state.direction = directions[event.key]
        return True

    def update(self) -> None:
        """Advance the snake one tick and apply collision/food rules."""
        assert self.state is not None
        x, y = self.state.snake[-1]
        dx, dy = self.state.direction
        head = (x + dx, y + dy)
        self.state.snake.append(head)

        outside = (
            head[0] >= self.settings.width
            or head[0] < 0
            or head[1] >= self.settings.height
            or head[1] < 0
        )
        if outside or collides_with_self(head, self.state.snake):
            self.state.game_over = True

        if head == self.state.food:
            self.state.food = random_food(self.settings)
        else:
            self.state.snake.pop(0)

    def draw(self, game_over: bool = False) -> None:
        """Render the current round or its game-over screen."""
        assert self.screen is not None
        assert self.state is not None
        assert self.font is not None
        assert self.score_font is not None
        self.screen.fill(self.settings.background)

        if game_over:
            message = self.font.render(
                "You Lost! Press Q-Quit or C-Play Again",
                True,
                self.settings.game_over_text,
            )
            self.screen.blit(
                message,
                (self.settings.width / 6, self.settings.height / 3),
            )
        else:
            pygame.draw.rect(
                self.screen,
                self.settings.food,
                (*self.state.food, self.settings.cell_size, self.settings.cell_size),
            )
            for x, y in self.state.snake:
                pygame.draw.rect(
                    self.screen,
                    self.settings.snake,
                    (x, y, self.settings.cell_size, self.settings.cell_size),
                )

        score = self.score_font.render(
            f"Your Score: {self.state.score}", True, self.settings.text
        )
        self.screen.blit(score, (0, 0))
        pygame.display.update()

    def run(self) -> None:
        """Run rounds until the user closes the window or chooses Q."""
        self.initialize()
        running = True
        try:
            while running:
                self.reset_round()
                while running and self.state is not None and not self.state.game_over:
                    running = self.handle_events()
                    if running:
                        self.update()
                        self.draw()
                        assert self.clock is not None
                        self.clock.tick(self.settings.frames_per_second)

                while running and self.state is not None and self.state.game_over:
                    self.draw(game_over=True)
                    for event in pygame.event.get():
                        if event.type == pygame.QUIT:
                            running = False
                        elif event.type == pygame.KEYDOWN:
                            if event.key == pygame.K_q:
                                running = False
                            elif event.key == pygame.K_c:
                                self.state.game_over = False
                                break
                    if running and self.state.game_over:
                        assert self.clock is not None
                        self.clock.tick(self.settings.frames_per_second)
        finally:
            pygame.quit()
